import { Suspense } from "react"
import type { Metadata } from "next"

import { dehydrate, HydrationBoundary, noop } from "@tanstack/react-query"
import { getTranslations, setRequestLocale } from "next-intl/server"

import { getPageAlternates } from "@/config/seo.config"

import { makeQueryClient } from "@/lib/query-client"

import { usersQueryOptions } from "@/features/users/api/user.queries"
import { UsersDirectory } from "@/features/users/components/UsersDirectory"
import { UsersDirectorySkeleton } from "@/features/users/components/UsersDirectorySkeleton"
import { UsersPage } from "@/features/users/components/UsersPage"
import { loadUsersParams } from "@/features/users/schemas/users-params.schema"

export async function generateMetadata({
  params
}: PageProps<"/[locale]/users">): Promise<Metadata> {
  const { locale } = await params
  const t = await getTranslations({ locale, namespace: "Users" })

  return {
    title: t("meta_title"),
    description: t("meta_description"),
    alternates: getPageAlternates(locale, "/users"),
    // A demo should not reach search results.
    robots: { index: false, follow: false }
  }
}

export default async function UsersRoute({ params, searchParams }: PageProps<"/[locale]/users">) {
  const { locale } = await params
  setRequestLocale(locale)

  return (
    <UsersPage>
      <Suspense fallback={<UsersDirectorySkeleton />}>
        <PrefetchedUsers searchParams={searchParams} />
      </Suspense>
    </UsersPage>
  )
}

// Reading searchParams makes this route dynamic, so `next build` never calls DummyJSON.
async function PrefetchedUsers({
  searchParams
}: Pick<PageProps<"/[locale]/users">, "searchParams">) {
  const filters = await loadUsersParams(searchParams)
  const queryClient = makeQueryClient()
  // A failed prefetch is not dehydrated: the client fetches again and shows the error state.
  await queryClient.query(usersQueryOptions(filters)).catch(noop)

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <UsersDirectory />
    </HydrationBoundary>
  )
}

import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { addUser } from "@/features/users/api/add-user.api"
import { server } from "@/test/server"

const ADD_USER_URL = "https://dummyjson.com/users/add"
const input = { firstName: "Ada", lastName: "Lovelace", email: "ada@example.com" }

describe("addUser", () => {
  it("posts the input and returns the created user", async () => {
    let body: unknown
    server.use(
      http.post(ADD_USER_URL, async ({ request }) => {
        body = await request.json()
        return HttpResponse.json({ id: 209, username: "", ...input }, { status: 201 })
      })
    )

    await expect(addUser(input)).resolves.toEqual({
      id: 209,
      username: "",
      role: "user",
      ...input
    })
    expect(body).toEqual(input)
  })
})

import { api } from "@/lib/api"

import { USERS_PATH } from "@/features/users/constants/users.constants"
import { userSchema } from "@/features/users/schemas/user.schema"
import type { AddUserInput, User } from "@/features/users/schemas/user.schema"

/** DummyJSON answers as if the user was created, but it does not store it. */
export function addUser(input: AddUserInput, signal?: AbortSignal): Promise<User> {
  return api.post(`${USERS_PATH}/add`, input, { schema: userSchema, signal })
}

import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { ApiError } from "@/lib/api"

import { getUsers } from "@/features/users/api/get-users.api"
import { server } from "@/test/server"

const USERS_URL = "https://dummyjson.com/users"

const ada = {
  id: 1,
  firstName: "Ada",
  lastName: "Lovelace",
  username: "ada",
  email: "ada@example.com",
  role: "admin",
  company: { title: "Mathematician", department: "Research" }
}

function pageOf(users: unknown[], skip = 0) {
  return { users, total: users.length, skip, limit: 10 }
}

describe("getUsers", () => {
  it("turns the page into limit and skip", async () => {
    let params: URLSearchParams | undefined
    server.use(
      http.get(USERS_URL, ({ request }) => {
        params = new URL(request.url).searchParams
        return HttpResponse.json(pageOf([ada], 20))
      })
    )

    await expect(getUsers({ page: 3, q: "" })).resolves.toEqual(pageOf([ada], 20))
    expect(params?.get("limit")).toBe("10")
    expect(params?.get("skip")).toBe("20")
    expect(params?.has("q")).toBe(false)
    expect(params?.get("sortBy")).toBe("lastName")
    expect(params?.get("order")).toBe("desc")
  })

  it("accepts a user without a company", async () => {
    const { company: _company, ...withoutCompany } = ada
    server.use(http.get(USERS_URL, () => HttpResponse.json(pageOf([withoutCompany]))))

    const { users } = await getUsers({ page: 1, q: "" })

    expect(users[0]?.company).toBeUndefined()
  })

  it("falls back to the user role when the API sends none", async () => {
    const { role: _role, ...noRole } = ada
    server.use(http.get(USERS_URL, () => HttpResponse.json(pageOf([noRole]))))

    const { users } = await getUsers({ page: 1, q: "" })

    expect(users[0]?.role).toBe("user")
  })

  it("uses the search endpoint and encodes the term", async () => {
    let params: URLSearchParams | undefined
    server.use(
      http.get(`${USERS_URL}/search`, ({ request }) => {
        params = new URL(request.url).searchParams
        return HttpResponse.json(pageOf([ada]))
      })
    )

    await getUsers({ page: 1, q: "  ada & co " })

    expect(params?.get("q")).toBe("ada & co")
    expect(params?.get("skip")).toBe("0")
  })

  it("treats a blank search as no search", async () => {
    server.use(http.get(USERS_URL, () => HttpResponse.json(pageOf([ada]))))

    await expect(getUsers({ page: 1, q: "   " })).resolves.toEqual(pageOf([ada]))
  })

  it("drops fields the app does not use", async () => {
    server.use(
      http.get(USERS_URL, () => HttpResponse.json(pageOf([{ ...ada, password: "secret" }])))
    )

    const { users } = await getUsers({ page: 1, q: "" })

    expect(users[0]).not.toHaveProperty("password")
  })

  it("throws an ApiError when the API fails", async () => {
    server.use(http.get(USERS_URL, () => HttpResponse.json({ message: "Down" }, { status: 503 })))

    await expect(getUsers({ page: 1, q: "" })).rejects.toMatchObject({
      name: "ApiError",
      status: 503
    })
  })

  it("throws an ApiError when the response has the wrong shape", async () => {
    server.use(http.get(USERS_URL, () => HttpResponse.json({ users: "nope" })))

    await expect(getUsers({ page: 1, q: "" })).rejects.toBeInstanceOf(ApiError)
  })
})

import { api } from "@/lib/api"

import { USERS_PAGE_SIZE, USERS_PATH } from "@/features/users/constants/users.constants"
import { usersPageSchema } from "@/features/users/schemas/user.schema"
import type { UsersPage } from "@/features/users/schemas/user.schema"
import type { UsersFilters } from "@/features/users/schemas/users-params.schema"

export function getUsers({ page, q }: UsersFilters, signal?: AbortSignal): Promise<UsersPage> {
  const search = q.trim()

  return api.get(search ? `${USERS_PATH}/search` : USERS_PATH, {
    params: {
      limit: USERS_PAGE_SIZE,
      skip: (page - 1) * USERS_PAGE_SIZE,
      q: search || undefined,
      // DummyJSON lists its admins first; this order looks like a real team.
      sortBy: "lastName",
      order: "desc"
    },
    schema: usersPageSchema,
    signal
  })
}

import type { UsersFilters } from "@/features/users/schemas/users-params.schema"

export const userKeys = {
  all: ["users"] as const,
  lists: () => [...userKeys.all, "list"] as const,
  list: (filters: UsersFilters) => [...userKeys.lists(), filters] as const
}

import { keepPreviousData, queryOptions } from "@tanstack/react-query"

import { getUsers } from "@/features/users/api/get-users.api"
import { userKeys } from "@/features/users/api/query-keys"
import type { UsersFilters } from "@/features/users/schemas/users-params.schema"

export const usersQueryOptions = ({ page, q }: UsersFilters) => {
  const filters = { page, q: q.trim() }

  return queryOptions({
    queryKey: userKeys.list(filters),
    queryFn: ({ signal }) => getUsers(filters, signal),
    placeholderData: keepPreviousData
  })
}

import { screen } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import type { UserEvent } from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { AddUserForm } from "@/features/users/components/AddUserForm"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const ADD_USER_URL = "https://dummyjson.com/users/add"

async function fillAndSubmit(user: UserEvent) {
  await user.type(screen.getByLabelText("First name"), "Ada")
  await user.type(screen.getByLabelText("Last name"), "Lovelace")
  await user.type(screen.getByLabelText("Email"), "ada@example.com")
  await user.click(screen.getByRole("button", { name: "Add user" }))
}

describe("AddUserForm", () => {
  it("shows validation errors and sends nothing while the input is invalid", async () => {
    let requests = 0
    server.use(
      http.post(ADD_USER_URL, () => {
        requests += 1
        return HttpResponse.json({})
      })
    )
    const user = userEvent.setup()
    renderWithProviders(<AddUserForm />)

    await user.type(screen.getByLabelText("Email"), "not-an-email")
    await user.click(screen.getByRole("button", { name: "Add user" }))

    expect(await screen.findByText("Enter a first name")).toBeInTheDocument()
    expect(screen.getByText("Enter a last name")).toBeInTheDocument()
    expect(screen.getByText("Enter a valid email address")).toBeInTheDocument()
    expect(screen.getByLabelText("Email")).toHaveAttribute("aria-invalid", "true")
    expect(requests).toBe(0)
  })

  it("shows the returned user and says the demo API does not save it", async () => {
    server.use(
      http.post(ADD_USER_URL, async ({ request }) => {
        const body = await request.clone().json()
        return HttpResponse.json({ ...Object(body), id: 209, username: "" }, { status: 201 })
      })
    )
    const user = userEvent.setup()
    renderWithProviders(<AddUserForm />)

    await fillAndSubmit(user)

    const result = await screen.findByRole("status")
    expect(result).toHaveTextContent("user #209")
    expect(result).toHaveTextContent("Ada Lovelace")
    expect(result).toHaveTextContent("ada@example.com")
    expect(result).toHaveTextContent(/not saved/i)
    expect(result).toHaveTextContent(/does not store it/i)
  })

  it("returns to an empty form for another user", async () => {
    server.use(
      http.post(ADD_USER_URL, () =>
        HttpResponse.json({
          id: 209,
          firstName: "Ada",
          lastName: "Lovelace",
          username: "",
          email: "ada@example.com"
        })
      )
    )
    const user = userEvent.setup()
    renderWithProviders(<AddUserForm />)

    await fillAndSubmit(user)
    await user.click(await screen.findByRole("button", { name: "Add another user" }))

    expect(screen.getByLabelText("First name")).toHaveValue("")
    expect(screen.queryByRole("status")).not.toBeInTheDocument()
  })

  it("shows an error and keeps the input when the request fails", async () => {
    server.use(http.post(ADD_USER_URL, () => HttpResponse.json({}, { status: 500 })))
    const user = userEvent.setup()
    renderWithProviders(<AddUserForm />)

    await fillAndSubmit(user)

    expect(await screen.findByRole("alert")).toHaveTextContent(/could not add the user/i)
    expect(screen.getByLabelText("First name")).toHaveValue("Ada")
  })
})

"use client"

import { zodResolver } from "@hookform/resolvers/zod"
import { useTranslations } from "next-intl"
import { Controller, useForm } from "react-hook-form"
import type { Control } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { useAddUser } from "@/features/users/hooks/use-add-user"
import { useErrorMessage } from "@/features/users/hooks/use-error-message"
import { createAddUserSchema } from "@/features/users/schemas/user.schema"
import type { AddUserInput } from "@/features/users/schemas/user.schema"

export function AddUserForm() {
  const t = useTranslations("Users")
  const getErrorMessage = useErrorMessage()
  const addUser = useAddUser()
  const form = useForm<AddUserInput>({
    resolver: zodResolver(createAddUserSchema(t)),
    defaultValues: { firstName: "", lastName: "", email: "" }
  })

  const onSubmit = form.handleSubmit(async (values) => {
    try {
      await addUser.mutateAsync(values)
    } catch (error) {
      form.setError("root.server", { message: getErrorMessage(error) })
    }
  })

  if (addUser.data) {
    const { id, firstName, lastName, email } = addUser.data

    return (
      <div role="status" className="flex flex-col gap-4">
        <div className="rounded-lg border p-4">
          <p className="text-xs text-muted-foreground">{t("add_result", { id })}</p>
          <p className="mt-1 font-medium">
            {firstName} {lastName}
          </p>
          <p className="text-sm break-all text-muted-foreground">{email}</p>
        </div>
        <p className="rounded-lg bg-muted p-4 text-sm">
          {t.rich("add_not_saved", {
            strong: (chunks) => <strong className="font-medium">{chunks}</strong>
          })}
        </p>
        <Button
          variant="outline"
          className="self-start"
          onClick={() => {
            addUser.reset()
            form.reset()
          }}
        >
          {t("add_another_user")}
        </Button>
      </div>
    )
  }

  const serverError = form.formState.errors.root?.server?.message

  return (
    <form onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
      <TextField control={form.control} name="firstName" label={t("field_first_name")} />
      <TextField control={form.control} name="lastName" label={t("field_last_name")} />
      <TextField control={form.control} name="email" label={t("field_email")} type="email" />
      {serverError && (
        <p role="alert" className="text-sm text-destructive">
          {t("add_error", { error: serverError })}
        </p>
      )}
      <Button type="submit" className="self-start" disabled={form.formState.isSubmitting}>
        {form.formState.isSubmitting ? t("adding_user") : t("add_user")}
      </Button>
    </form>
  )
}

type TextFieldProps = {
  control: Control<AddUserInput>
  name: keyof AddUserInput
  label: string
  type?: "text" | "email"
}

function TextField({ control, name, label, type = "text" }: TextFieldProps) {
  return (
    <Controller
      name={name}
      control={control}
      render={({ field, fieldState }) => (
        <Field data-invalid={fieldState.invalid}>
          <FieldLabel htmlFor={field.name}>{label}</FieldLabel>
          <Input
            {...field}
            id={field.name}
            type={type}
            aria-invalid={fieldState.invalid}
            aria-describedby={fieldState.invalid ? `${field.name}-error` : undefined}
          />
          {fieldState.invalid && (
            <FieldError id={`${field.name}-error`} errors={[fieldState.error]} />
          )}
        </Field>
      )}
    />
  )
}

import { screen } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { beforeEach, describe, expect, it } from "vitest"

import { FavoriteButton } from "@/features/users/components/FavoriteButton"
import { FavoritesCount } from "@/features/users/components/FavoritesCount"
import { useFavoritesStore } from "@/features/users/stores/favorites.store"
import { renderWithProviders } from "@/test/render"

function renderFavorites() {
  return renderWithProviders(
    <>
      <FavoritesCount />
      <FavoriteButton userId={1} userName="Ada Lovelace" />
      <FavoriteButton userId={2} userName="Grace Hopper" />
    </>
  )
}

describe("favorites", () => {
  beforeEach(() => {
    useFavoritesStore.setState({ ids: [] })
  })

  it("adds a user and updates the count", async () => {
    const user = userEvent.setup()
    renderFavorites()
    expect(screen.getByText(/favorites/)).toHaveTextContent("0 favorites")

    const ada = screen.getByRole("button", { name: "Favorite Ada Lovelace" })
    await user.click(ada)

    expect(ada).toHaveAttribute("aria-pressed", "true")
    expect(screen.getByRole("button", { name: "Favorite Grace Hopper" })).toHaveAttribute(
      "aria-pressed",
      "false"
    )
    expect(screen.getByText(/favorite$/)).toHaveTextContent("1 favorite")
  })

  it("removes a user on the second press", async () => {
    const user = userEvent.setup()
    renderFavorites()

    const ada = screen.getByRole("button", { name: "Favorite Ada Lovelace" })
    await user.click(ada)
    await user.click(ada)

    expect(ada).toHaveAttribute("aria-pressed", "false")
    expect(screen.getByText(/favorites/)).toHaveTextContent("0 favorites")
  })

  it("counts every favorite and remembers them in the browser", async () => {
    const user = userEvent.setup()
    renderFavorites()

    await user.click(screen.getByRole("button", { name: "Favorite Ada Lovelace" }))
    await user.click(screen.getByRole("button", { name: "Favorite Grace Hopper" }))

    expect(screen.getByText(/favorites/)).toHaveTextContent("2 favorites")
    expect(localStorage.getItem("favorite-users")).toContain("[1,2]")
  })
})

"use client"

import { StarIcon } from "lucide-react"
import { cn } from "cn"
import { useTranslations } from "next-intl"

import { Button } from "@/components/ui/button"
import { useFavoriteIds } from "@/features/users/hooks/use-favorite-ids"
import { useFavoritesStore } from "@/features/users/stores/favorites.store"

type FavoriteButtonProps = {
  userId: number
  userName: string
}

export function FavoriteButton({ userId, userName }: FavoriteButtonProps) {
  const t = useTranslations("Users")
  const isFavorite = useFavoriteIds().includes(userId)
  const toggle = useFavoritesStore((state) => state.toggle)

  return (
    <Button
      variant="ghost"
      size="icon"
      aria-label={t("favorite_user", { name: userName })}
      aria-pressed={isFavorite}
      onClick={() => toggle(userId)}
    >
      <StarIcon
        aria-hidden
        className={cn("size-4", isFavorite && "fill-amber-400 text-amber-400")}
      />
    </Button>
  )
}

"use client"

import { useTranslations } from "next-intl"

import { useFavoriteIds } from "@/features/users/hooks/use-favorite-ids"

export function FavoritesCount() {
  const t = useTranslations("Users")
  const count = useFavoriteIds().length

  return (
    <p aria-live="polite" className="text-sm whitespace-nowrap">
      {t.rich("favorites_count", {
        count,
        number: (chunks) => <span className="tabular-nums">{chunks}</span>
      })}
    </p>
  )
}

import { screen, waitFor } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import type { UrlUpdateEvent } from "nuqs/adapters/testing"
import { describe, expect, it, vi } from "vitest"

import { UsersDirectory } from "@/features/users/components/UsersDirectory"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const USERS_URL = "https://dummyjson.com/users"

function userNamed(id: number, firstName: string) {
  return {
    id,
    firstName,
    lastName: "Test",
    username: firstName.toLowerCase(),
    email: `${firstName.toLowerCase()}@example.com`
  }
}

function pageOf(firstName: string, total = 25) {
  return { users: [userNamed(1, firstName)], total, skip: 0, limit: 10 }
}

function renderDirectory(searchParams = "", onUrlUpdate?: (event: UrlUpdateEvent) => void) {
  return renderWithProviders(<UsersDirectory />, { searchParams, onUrlUpdate })
}

describe("UsersDirectory", () => {
  it("shows a loading state, then the users", async () => {
    server.use(http.get(USERS_URL, () => HttpResponse.json(pageOf("Ada"))))
    renderDirectory()

    expect(screen.getByRole("status", { name: "Loading users" })).toBeInTheDocument()

    expect(await screen.findByText("Ada Test")).toBeInTheDocument()
    expect(screen.getByText("Page 1 of 3")).toBeInTheDocument()
    expect(screen.getByRole("button", { name: "Previous" })).toHaveAttribute(
      "aria-disabled",
      "true"
    )
  })

  it("opens the view stored in the URL", async () => {
    server.use(
      http.get(`${USERS_URL}/search`, ({ request }) => {
        const params = new URL(request.url).searchParams
        const matches = params.get("q") === "ada" && params.get("skip") === "10"
        return HttpResponse.json(pageOf(matches ? "Ada" : "Wrong"))
      })
    )
    renderDirectory("?page=2&q=ada")

    expect(await screen.findByText("Ada Test")).toBeInTheDocument()
    expect(screen.getByLabelText("Search users")).toHaveValue("ada")
    expect(screen.getByText("Page 2 of 3")).toBeInTheDocument()
  })

  it("falls back to the first page when the URL page is invalid", async () => {
    server.use(http.get(USERS_URL, () => HttpResponse.json(pageOf("Ada"))))
    renderDirectory("?page=-2")

    expect(await screen.findByText("Page 1 of 3")).toBeInTheDocument()
  })

  it("stores the next page in the URL", async () => {
    server.use(
      http.get(USERS_URL, ({ request }) => {
        const skip = new URL(request.url).searchParams.get("skip")
        return HttpResponse.json(pageOf(skip === "10" ? "Grace" : "Ada"))
      })
    )
    const onUrlUpdate = vi.fn<(event: UrlUpdateEvent) => void>()
    const user = userEvent.setup()
    renderDirectory("", onUrlUpdate)

    await screen.findByText("Ada Test")
    await user.click(screen.getByRole("button", { name: "Next" }))

    expect(await screen.findByText("Grace Test")).toBeInTheDocument()
    expect(onUrlUpdate.mock.lastCall?.[0].queryString).toBe("?page=2")
  })

  it("goes back to the first page when the search changes", async () => {
    server.use(
      http.get(USERS_URL, () => HttpResponse.json(pageOf("Ada"))),
      http.get(`${USERS_URL}/search`, ({ request }) => {
        const params = new URL(request.url).searchParams
        const matches = params.get("q") === "gr" && params.get("skip") === "0"
        return HttpResponse.json(pageOf(matches ? "Grace" : "Wrong", 1))
      })
    )
    const onUrlUpdate = vi.fn<(event: UrlUpdateEvent) => void>()
    const user = userEvent.setup()
    renderDirectory("?page=2", onUrlUpdate)

    await screen.findByText("Ada Test")
    await user.type(screen.getByLabelText("Search users"), "gr")

    expect(await screen.findByText("Grace Test")).toBeInTheDocument()
    await waitFor(() => expect(onUrlUpdate.mock.lastCall?.[0].queryString).toBe("?q=gr"))
  })

  it("shows an empty state that can clear the search", async () => {
    server.use(
      http.get(`${USERS_URL}/search`, () =>
        HttpResponse.json({ users: [], total: 0, skip: 0, limit: 0 })
      ),
      http.get(USERS_URL, () => HttpResponse.json(pageOf("Ada")))
    )
    const user = userEvent.setup()
    renderDirectory("?q=nobody")

    expect(await screen.findByText("No users found")).toBeInTheDocument()
    await user.click(screen.getByRole("button", { name: "Clear search" }))

    expect(await screen.findByText("Ada Test")).toBeInTheDocument()
    expect(screen.getByLabelText("Search users")).toHaveValue("")
  })

  it("offers the first page when the URL points past the last one", async () => {
    server.use(
      http.get(USERS_URL, ({ request }) => {
        const skip = new URL(request.url).searchParams.get("skip")
        return HttpResponse.json(
          skip === "0" ? pageOf("Ada") : { users: [], total: 25, skip: 90, limit: 10 }
        )
      })
    )
    const user = userEvent.setup()
    renderDirectory("?page=10")

    expect(await screen.findByText("This page is empty")).toBeInTheDocument()
    await user.click(screen.getByRole("button", { name: "Go to the first page" }))

    expect(await screen.findByText("Ada Test")).toBeInTheDocument()
  })

  it("shows an error state and recovers with retry", async () => {
    let requests = 0
    server.use(
      http.get(USERS_URL, () => {
        requests += 1
        return requests === 1
          ? HttpResponse.json({}, { status: 503 })
          : HttpResponse.json(pageOf("Ada"))
      })
    )
    const user = userEvent.setup()
    renderDirectory()

    expect(await screen.findByRole("alert")).toHaveTextContent("Could not load users")
    await user.click(screen.getByRole("button", { name: "Retry" }))

    expect(await screen.findByText("Ada Test")).toBeInTheDocument()
  })

  it("shows the position, department and role of a user", async () => {
    const ada = {
      ...userNamed(1, "Ada"),
      role: "admin",
      company: { title: "Mathematician", department: "Research" }
    }
    server.use(
      http.get(USERS_URL, () =>
        HttpResponse.json({ users: [ada, userNamed(2, "Grace")], total: 2, skip: 0, limit: 10 })
      )
    )
    renderDirectory()

    expect(await screen.findByText("Mathematician")).toBeInTheDocument()
    expect(screen.getByText("Research")).toBeInTheDocument()
    expect(screen.getAllByText(/^admin$/i)[0]).toBeInTheDocument()
    expect(screen.getByText("—")).toBeInTheDocument()
  })

  it("sends one search request for a burst of typing", async () => {
    const user = userEvent.setup()
    const searches: Array<string | null> = []
    server.use(
      http.get(USERS_URL, () => HttpResponse.json(pageOf("Ada"))),
      http.get(`${USERS_URL}/search`, ({ request }) => {
        searches.push(new URL(request.url).searchParams.get("q"))
        return HttpResponse.json(pageOf("Grace"))
      })
    )
    renderDirectory()
    await screen.findByText("Ada Test")

    await user.type(screen.getByLabelText("Search users"), "grace")

    expect(await screen.findByText("Grace Test")).toBeInTheDocument()
    expect(searches).toEqual(["grace"])
  })
})

