import type { useTranslations } from "next-intl"
import { z } from "zod"

export const userRoleSchema = z.enum(["admin", "moderator", "user"])

// Unknown keys are dropped on purpose: DummyJSON also returns passwords, bank and SSN fields.
export const userSchema = z.object({
  id: z.number(),
  firstName: z.string(),
  lastName: z.string(),
  username: z.string(),
  email: z.email(),
  role: userRoleSchema.default("user"),
  // A new user comes back from `POST /users/add` without a company.
  company: z.object({ title: z.string(), department: z.string() }).optional()
})

export const usersPageSchema = z.object({
  users: userSchema.array(),
  total: z.number(),
  skip: z.number(),
  limit: z.number()
})

/** A factory, so validation errors come in the visitor's language. */
export function createAddUserSchema(t: ReturnType<typeof useTranslations<"Users">>) {
  return z.object({
    firstName: z
      .string()
      .trim()
      .min(1, t("validation_first_name"))
      .max(50, t("validation_max_length")),
    lastName: z
      .string()
      .trim()
      .min(1, t("validation_last_name"))
      .max(50, t("validation_max_length")),
    email: z.email(t("validation_email"))
  })
}

export type User = z.infer<typeof userSchema>
export type UserRole = z.infer<typeof userRoleSchema>
export type UsersPage = z.infer<typeof usersPageSchema>
export type AddUserInput = z.infer<ReturnType<typeof createAddUserSchema>>

import { createLoader, createParser, parseAsString } from "nuqs/server"
import type { inferParserType } from "nuqs/server"
import { z } from "zod"

const pageSchema = z.coerce.number().int().positive()

const parseAsPage = createParser({
  parse: (value) => {
    const result = pageSchema.safeParse(value)
    return result.success ? result.data : null
  },
  serialize: String
})

/** Shared by the server loader and the client hook, so both read the same view from the URL. */
export const usersSearchParams = {
  page: parseAsPage.withDefault(1),
  q: parseAsString.withDefault("")
}

export const loadUsersParams = createLoader(usersSearchParams)

export type UsersFilters = inferParserType<typeof usersSearchParams>

import { create } from "zustand"
import { createJSONStorage, persist } from "zustand/middleware"

type FavoritesState = {
  /** Only ids: the user data itself stays in the Query cache. */
  ids: number[]
  toggle: (id: number) => void
}

// Client-only UI state, so a module-level store is fine.
export const useFavoritesStore = create<FavoritesState>()(
  persist(
    (set) => ({
      ids: [],
      toggle: (id) =>
        set((state) => ({
          ids: state.ids.includes(id)
            ? state.ids.filter((favoriteId) => favoriteId !== id)
            : [...state.ids, id]
        }))
    }),
    { name: "favorite-users", storage: createJSONStorage(() => localStorage) }
  )
)
